#!/usr/bin/env python3
"""Build the workbench's generated files.

- maps.js           <- maps/manifest.json (+ the map JSON files it lists)
- AI_MAP_KIT.md     <- AI_GUIDE.md + AI_MAP_SPEC.md + AI_MAP_SAMPLE.json + maps/sample-multifloor.json
- AI_MAP_SPEC.html, AI_GUIDE.html <- the .md files (needs `pip install markdown`; skipped if missing)

The map JSON files are the source; maps.js is only an offline (file://) wrapper.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8")

ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / "maps" / "manifest.json"
SPEC = ROOT / "AI_MAP_SPEC.md"
GUIDE = ROOT / "AI_GUIDE.md"
SAMPLE = ROOT / "AI_MAP_SAMPLE.json"
MULTI_SAMPLE = ROOT / "maps" / "sample-multifloor.json"


def compact(value):
    if isinstance(value, dict):
        return {key: compact(item) for key, item in value.items() if item is not None}
    if isinstance(value, list):
        return [compact(item) for item in value]
    return value


def build_maps() -> None:
    manifest = json.loads(MANIFEST.read_text(encoding="utf-8"))
    maps = {}
    for entry in manifest["maps"]:
        key, relative = entry["key"], entry["file"]
        if key in maps:
            raise ValueError(f"duplicate map key: {key}")
        maps[key] = compact(json.loads((ROOT / relative).read_text(encoding="utf-8-sig")))
        data = maps[key]
        print(f"{key}: rooms={len(data.get('rooms', []))} objects={len(data.get('objects', []))} "
              f"enemies={len(data.get('enemies', []))} floors={len(data.get('floors', []))}")
    wrapper = ("/* Generated by tools/build.py from maps/manifest.json; do not edit. */\n"
               "window.WORKBENCH_MAPS=" + json.dumps(maps, ensure_ascii=False, separators=(",", ":")) + ";\n")
    (ROOT / "maps.js").write_text(wrapper, encoding="utf-8")
    print("wrote maps.js")


def build_kit() -> None:
    guide = GUIDE.read_text(encoding="utf-8").strip()
    spec = SPEC.read_text(encoding="utf-8").strip()
    sample_text = json.dumps(json.loads(SAMPLE.read_text(encoding="utf-8")), ensure_ascii=False, indent=2)
    multi_text = json.dumps(json.loads(MULTI_SAMPLE.read_text(encoding="utf-8")), ensure_ascii=False, indent=2)
    body = f"""<!-- Generated by tools/build.py; edit AI_GUIDE.md / AI_MAP_SPEC.md / the sample JSONs instead. -->
# AI 关卡设计 · 单文件包

> 把本文件整个交给任意 AI。顺序：① 工作台与设计指南 ② 字段规范 ③ 两个完整示例。
> AI 只需要输出一份 JSON；不要输出解释或 Markdown 代码块。
> 机器契约：`AI_MAP_SPEC.schema.json`；校验：`python tools/validate_ai_map.py <file>`。

---

{guide}

---

{spec}

---

## 完整示例 A：单层（可直接照这个结构输出）

```json
{sample_text}
```

## 完整示例 B：三层 + 可选 3D 字段（露天 `wallHeight: 0`、楼梯 `bottom`、跨层路线 `[x,z,y]`）

```json
{multi_text}
```
"""
    (ROOT / "AI_MAP_KIT.md").write_text(body.rstrip() + "\n", encoding="utf-8")
    print("wrote AI_MAP_KIT.md")


def build_doc_page(source: Path, title: str) -> None:
    """Render a .md doc to a UTF-8 HTML page (some browsers show raw .md without a charset)."""
    try:
        import markdown
    except ImportError:
        print(f"skip {source.stem}.html (pip install markdown)")
        return
    body = markdown.Markdown(extensions=["tables", "fenced_code", "sane_lists"]).convert(source.read_text(encoding="utf-8"))
    page = f"""<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title} · 工作台</title>
<style>
:root{{--ink:#1e2420;--muted:#6f6d60;--line:#e0dbc9;--paper:#fffdf6;--accent:#44593f;--code:#f6f2e6}}
*{{box-sizing:border-box}}
body{{margin:0;background:#f8f5ea;color:var(--ink);font:14px/1.7 "Microsoft YaHei","Segoe UI",sans-serif}}
header{{position:sticky;top:0;z-index:2;display:flex;align-items:center;gap:12px;padding:12px 24px;background:var(--paper);border-bottom:1px solid var(--line)}}
header b{{font-size:15px}} header a{{margin-left:auto;color:var(--accent);text-decoration:none;font-size:12px}}
header .download{{border:1px solid var(--line);border-radius:6px;padding:5px 9px;color:var(--ink)}}
main{{max-width:980px;margin:22px auto 60px;padding:0 22px}}
article{{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:24px 30px;box-shadow:0 4px 14px #2c2a1f14}}
h1{{font-size:26px;margin:0 0 6px}} h2{{font-size:18px;margin:30px 0 8px;border-top:1px solid var(--line);padding-top:18px}}
h3{{font-size:14px;margin:20px 0 6px;color:var(--accent)}}
p{{color:#3c4239}} a{{color:var(--accent)}}
code{{background:var(--code);padding:1px 4px;border-radius:4px;font-family:Consolas,monospace;font-size:12px}}
pre{{background:#1e2420;color:#f6f2e6;padding:14px 16px;border-radius:8px;overflow:auto;line-height:1.5}}
pre code{{background:none;padding:0;color:inherit;font-size:12px}}
table{{border-collapse:collapse;width:100%;margin:10px 0;font-size:12px}}
th,td{{border:1px solid var(--line);padding:6px 8px;text-align:left;vertical-align:top}}
th{{background:#f6f2e6}} blockquote{{margin:12px 0;padding:8px 14px;border-left:3px solid #6e8b6a;background:#e6eddf;color:#44593f}}
ul,ol{{padding-left:22px}} li{{margin:4px 0}}
@media(max-width:700px){{article{{padding:16px}} main{{padding:0 10px}}}}
</style>
</head>
<body>
<header><b>{title}</b><a href="index.html">← 返回工作台</a><a class="download" href="AI_MAP_KIT.md" download>下载给 AI 的单文件包</a></header>
<main><article>{body}</article></main>
</body>
</html>
"""
    out = source.with_suffix(".html")
    out.write_text(page, encoding="utf-8")
    print(f"wrote {out.name}")


def main() -> int:
    build_maps()
    build_kit()
    build_doc_page(GUIDE, "AI 关卡设计指南")
    build_doc_page(SPEC, "AI 关卡输出规范")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
